"""Measure a separator-normalisation rule: a value equal to a stored spelling with
its separators removed (or added) rewritten to the stored spelling."""
import json, sys, re, glob, collections
sys.path.insert(0,'/tmp/r9'); sys.path.insert(0,'/workspace/harness/solver')
from replay import parse, extract, text_of
import answer_space as asp, adjudication as adj
SEPS=";；,，、|/"

def norm_rule(text, values):
    def nop(s): return "".join(ch for ch in s if ch not in SEPS)
    hit={}
    for v in values:
        hit.setdefault(nop(v), []).append(v)
    preds=[v.strip() for v in re.split(r"[;；,，]", text) if v.strip()]
    out=[]; applied=0
    for p in preds:
        cands=hit.get(nop(p), [])
        if p not in values and len(cands)==1 and cands[0]!=p:
            out.append(cands[0]); applied+=1
        else:
            out.append(p)
    return ";".join(out) if applied else text, applied

def analyse(run_dir, task='LawBench'):
    mp=f'{run_dir}/{task}/memory.json'
    values=asp.build_index(mp)[0]
    rows={}
    for line in open(f'{run_dir}/results/samples.jsonl'):
        r=json.loads(line)
        if r['task']==task: rows[(r['example_index'],r['sample_index'])]=r
    res=collections.Counter(); det=[]
    for (i,s),r in sorted(rows.items()):
        convf=f'{run_dir}/{task}/conversations/{i:04d}/sample-{s}.json'
        aa=None; pairs=None
        for sc in (json.load(open(convf)).get('side_calls') or []):
            if not isinstance(sc,list) or len(sc)<2: continue
            p=text_of(sc[0])
            if 'An agent answered the problem below' in p: aa,pairs=extract(p,text_of(sc[1]))
        if aa is None: continue
        base=aa
        if pairs is not None: base,_=adj.rewrite(base, adj.accepted(pairs, values))
        conv=asp.edge_conventions(asp.stored_values(mp))
        a,_=asp.canonicalize(base,asp.build_index(mp)); a,_=asp.trim_trailing(a,asp.build_index(mp),conv); a,_=asp.complete_compound(a,asp.build_index(mp))
        tset=parse(r['target'],task); ok0=parse(a,task)==tset
        m=re.search(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"', a)
        ans=m.group(1) if m else a
        new,n=norm_rule(ans, values)
        newmsg = (a[:m.start(1)]+new+a[m.end(1):]) if m else new
        ok1=parse(newmsg,task)==tset
        if n:
            res['fired']+=1
            if ok1 and not ok0: res['win']+=1; det.append((i,s,'WIN',ans,new))
            elif ok0 and not ok1: res['loss']+=1; det.append((i,s,'LOSS',ans,new))
            else: det.append((i,s,'--',ans,new))
        res['n']+=1
    return res,det

if __name__=='__main__':
    for run in ['9f49dd72','8a4e7e02','c40638ad','84ec2cc2','91f82d64','b31e34da','554cf786','80a50a61','4621bcdd']:
        d=glob.glob(f'/workspace/runs/{run}*')[0]
        res,det=analyse(d)
        print(f'{run}: n={res["n"]} fired={res["fired"]} win=+{res["win"]} loss=-{res["loss"]}')
        for x in det[:6]: print('     ',x)
