"""Probe: does a two-tier evidence rendering (full cases + compact answer tail)
change the model's answer, against the evidence the recorded agent actually saw?"""
import json, os, re, sys, collections, concurrent.futures as cf
sys.path.insert(0,'/tmp/r9')
from rank import ngrams, idf, wnorm, cos, MAX_CHARS
from openai import OpenAI

client = OpenAI(base_url="https://dashscope.aliyuncs.com/compatible-mode/v1",
                api_key=os.environ["BAILIAN_API_KEY"], timeout=300)
MODEL="qwen3.7-flash"
run=sys.argv[1]
mem=json.load(open(f'{run}/LawBench/memory.json'))['examples']
questions=[e.get('raw_question', e['input']) for e in mem]
answers=[str(e['target']).strip() for e in mem]
rows=[json.loads(l) for l in open(f'{run}/results/samples.jsonl')]
seen={(r['example_index'],r['sample_index']):r for r in rows if r['task']=='LawBench'}
qd=[ngrams(q) for q in questions]; wq=idf(qd)
def q_order(inp):
    q=ngrams(inp); qn=wnorm(q,wq); sc=[cos(q,d,wq,qn,wnorm(d,wq)) for d in qd]
    return sorted(range(len(mem)), key=lambda j:(-sc[j],j))
SENT=re.compile(r"[。！？\n]")
def best_part(text, inp, keep):
    parts=[p.strip() for p in SENT.split(text) if p.strip()]
    if len(parts)<=1: return text
    q=ngrams(inp)
    scored=sorted(range(len(parts)), key=lambda k: (-sum(1 for g in set(ngrams(parts[k])) if g in q), k))
    total=sum(len(p) for p in parts); budget=max(int(total*keep),60)
    out=[]; used=0
    for k in scored:
        if used+len(parts[k])>budget and out: continue
        out.append(k); used+=len(parts[k])
        if used>=budget: break
    return "。".join(parts[k] for k in sorted(out))
def tiered(inp, share=0.5, keep=0.15):
    full_cap=int(MAX_CHARS*share); parts=[]; total=0; tier='full'
    for j in q_order(inp):
        if tier=='full':
            part=f"Q: {questions[j]}\nA: {answers[j]}"
            if total+len(part)<=full_cap:
                parts.append(part); total+=len(part)+2; continue
            tier='compact'
        part=f"Q: {best_part(questions[j], inp, keep)}\nA: {answers[j]}"
        if total+len(part)>MAX_CHARS: continue
        parts.append(part); total+=len(part)+2
    return "\n\n".join(parts)
def answeronly(inp, share=0.5):
    full_cap=int(MAX_CHARS*share); parts=[]; total=0; tier='full'
    for j in q_order(inp):
        if tier=='full':
            part=f"Q: {questions[j]}\nA: {answers[j]}"
            if total+len(part)<=full_cap:
                parts.append(part); total+=len(part)+2; continue
            tier='compact'
        part=f"A: {answers[j]}"
        if total+len(part)>MAX_CHARS: continue
        parts.append(part); total+=len(part)+2
    return "\n\n".join(parts)
def recorded_evidence(i,s):
    d=json.load(open(f'{run}/LawBench/conversations/{i:04d}/sample-{s}.json'))
    out=[]
    for m in d['messages']:
        if m.get('role')=='tool':
            c=m.get('content')
            if isinstance(c,list): c=''.join(b.get('text','') for b in c if isinstance(b,dict))
            out.append(c or '')
    return "\n\n".join(out)
def vals(s): return {x.strip() for x in re.split(r"[;；,，、]", s) if x.strip()}
def parse(p):
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)",p)
    t=m.group(1).strip() if m else re.sub(r"<eoa>.*","",p).strip()
    return vals(t)
def ask(payload):
    inp, evidence = payload
    content=f"{inp}\n\n## Examples from the frozen memory\n\n{evidence}"
    try:
        r=client.chat.completions.create(model=MODEL, temperature=0.0, max_tokens=16384,
            extra_body={"enable_thinking": True},
            messages=[{"role":"system","content":"You are an agent that answers a question by retrieving examples."},
                      {"role":"user","content":content}])
        return r.choices[0].message.content or ""
    except Exception as e:
        return f"ERROR::{e}"
records=[]
for (i,s),r in sorted(seen.items()):
    d=json.load(open(f'{run}/LawBench/conversations/{i:04d}/sample-{s}.json'))
    c=d['messages'][1]['content']
    inp=c[0]['text'] if isinstance(c,list) else c
    records.append(((i,s),r,inp))
conditions={'A_recorded':lambda i,s,inp: recorded_evidence(i,s),
            'B_tier':lambda i,s,inp: tiered(inp),
            'C_answeronly':lambda i,s,inp: answeronly(inp)}
results={k:{} for k in conditions}
for name,fn in conditions.items():
    payloads=[(inp, fn(i,s,inp)) for ((i,s),r,inp) in records]
    with cf.ThreadPoolExecutor(max_workers=16) as ex:
        resp=list(ex.map(ask,payloads))
