        m=re.search(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"', rs)
        ans=(m.group(1) if m else rs)
        results[name][(i,s)]=(parse(ans)==parse(r['target']), ans, r['was_correct'], r['target'])
