import json,re
P='/workspace/runs/4621bcdd04680865c575918afaf12e57c1d972f0'; N='/workspace/runs/806c3bdaca840f15a97e4bcead1bae6941fb83fb'
def tool_text(d,task,i,s):
    conv=json.load(open(f'{d}/{task}/conversations/{i:04d}/sample-{s}.json'))
    out=[]
    for m in conv['messages']:
        if m.get('role')=='tool':
            c=m.get('content')
            if isinstance(c,list): c=''.join(b.get('text','') for b in c if isinstance(b,dict))
            out.append(c or '')
    return '\n'.join(out)
def charges(p):
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)",p)
    t=m.group(1).strip() if m else re.sub(r"<eoa>.*","",p).strip()
    return [x.strip() for x in re.split(r"[;；,，、]",t) if x.strip()]
for i,s in ((31,0),(43,0),(46,0),(13,0)):
    for tk,label in ((P,'parent'),(N,'new')):
        rows={(r['example_index'],r['sample_index']):r for r in map(json.loads,open(tk+'/results/samples.jsonl')) if r['task']=='LawBench'}
        r=rows[(i,s)]
        txt=tool_text(tk,'LawBench',i,s)
        q=txt.count('\nQ: ')+ (1 if txt.startswith('Q: ') else 0)
        tail=sum(1 for line in txt.split('\n') if line.startswith('A: '))  # approximate
        tgt=r['target'].strip()
        present=all(any(c==ch for ch in charges(txt)) for c in charges(tgt))
        print(f'{i}-{s} {label:6s} Q-blocks {q:>3} A-lines {tail:>4} | whole-target-answer in evidence: {("A: "+tgt) in txt} | all target charges in evidence: {present} | pred {r["prediction"][:46]!r} ok={r["was_correct"]}')
    print()
